package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen4Test {

    @Test
    public void testAbbreviate_NullString() {
        assertNull(WordUtils.abbreviate(null, 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_EmptyString() {
        assertEquals("", WordUtils.abbreviate("", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_UpperIsNegativeOne() {
        // upper = -1 should set upper to str.length()
        // result: "Hello World" (no abbreviation because upper == length)
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, -1, "..."));
    }

    @Test
    public void testAbbreviate_UpperGreaterThanLength() {
        // upper > length should set upper to str.length()
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, 50, "..."));
    }

    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // upper < lower should set upper to lower
        // str="Hello", lower=4, upper=2 -> upper becomes 4. 
        // index of space is -1. upper(4) != length(5), so append "..."
        assertEquals("Hell...", WordUtils.abbreviate("Hello", 4, 2, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceFoundAndAbbreviationOccurs() {
        // index = -1. upper < length.
        assertEquals("Hell...", WordUtils.abbreviate("Hello", 0, 4, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceFoundAndNoAbbreviation() {
        // index = -1. upper == length.
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFoundAfterUpper() {
        // index of space is 6. upper is 4. index > upper.
        // result: str.substring(0, 4) + "..."
        assertEquals("Hell...", WordUtils.abbreviate("Hello World", 0, 4, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFoundBeforeUpper() {
        // index of space is 5. upper is 10. index <= upper.
        // result: str.substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 10, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFoundExactlyAtUpper() {
        // index of space is 5. upper is 5. index <= upper.
        // result: str.substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_NullAppendToEnd() {
        // Testing StringUtils.defaultString(appendToEnd) when appendToEnd is null
        // index of space is 6. upper is 4. index > upper.
        assertEquals("Hell", WordUtils.abbreviate("Hello World", 0, 4, null));
    }

    @Test
    public void testAbbreviate_LowerIndexCheck() {
        // index of space starts search from 'lower'
        // "Hello World" -> space at 5. If lower is 6, index is -1.
        assertEquals("Hello W...", WordUtils.abbreviate("Hello World", 6, 10, "..."));
    }
}
